import { createConnection } from 'node:net'
import { randomUUID } from 'node:crypto'
import { EventEmitter } from 'node:events'
import WebSocket from 'ws'
import { connectionTarget, authorization } from '../desktop-runtime/endpoint.mjs'
import { sameProfile } from './profile'

// Contract subset generated by desktop CLI 0.162.0-alpha.17.2. No private stdio.
export const schemaVersion = '0.162.0-alpha.17.2'
export interface ServerIdentity { userAgent: string; codexHome: string; platformOs: string; platformFamily: string }
export interface NativeTurn { id: string; status: 'inProgress' | 'completed' | 'interrupted' | 'failed'; items?: unknown[] }
export interface NativeThread { id: string; status: { type: string }; turns?: NativeTurn[] }
export interface NativeMessage { method: string; params?: unknown }
export interface ServerRequest extends NativeMessage { id: string | number }

export class RpcError extends Error {
  constructor(readonly code: number, message: string) { super(message) }
}
export class RpcUnavailable extends Error {
  constructor(message: string, readonly sent: boolean) { super(message) }
}
interface Pending { resolve(value: unknown): void; reject(error: Error): void; cleanup(): void }

/** One connection, with no automatic replay. Notifications and requests stay separate. */
export class AppServer extends EventEmitter {
  private pending = new Map<string, Pending>()
  private prefix = randomUUID()
  private seq = 0
  private ready = false
  private constructor(private socket: WebSocket, readonly timeoutMs: number) {
    super()
    socket.on('message', (data, binary) => {
      try {
        if (binary) throw new Error('Unexpected binary RPC message')
        const value = JSON.parse(data.toString())
        if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Invalid RPC message')
        if (typeof value.method === 'string') {
          if (value.id !== undefined) this.emit('serverRequest', value as ServerRequest)
          else this.emit('notification', value as NativeMessage)
          return
        }
        const pending = this.pending.get(String(value.id))
        if (!pending) return // Late response to an expired request is not a new admission.
        if ('error' in value) {
          if (!value.error || typeof value.error.code !== 'number' || typeof value.error.message !== 'string') throw new Error('Invalid RPC error')
          this.finish(String(value.id), new RpcError(value.error.code, value.error.message))
        } else if ('result' in value) this.finish(String(value.id), undefined, value.result)
        else throw new Error('Missing RPC result')
      } catch { this.fail('Invalid App Server RPC message'); socket.terminate() }
    })
    socket.on('error', () => this.fail('App Server connection failed'))
    socket.on('close', () => { this.fail('App Server connection closed'); this.emit('disconnected') })
  }

  static async connect(endpoint: string, options: { signal?: AbortSignal; timeoutMs?: number; expectedHome?: string; experimental?: boolean; tokenFile?: string } = {}) {
    const target = connectionTarget(endpoint, options.tokenFile)
    const timeoutMs = options.timeoutMs ?? 15_000
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) throw new Error('RPC timeout must be positive')
    options.signal?.throwIfAborted()
    const socket = new WebSocket(target.url ?? 'ws+unix://localhost/socket:/rpc', {
      ...(target.socketPath ? { createConnection: () => createConnection({ path: target.socketPath }) } : { headers: authorization(target.tokenFile!) }),
      handshakeTimeout: timeoutMs, maxPayload: 32 * 1024 * 1024, perMessageDeflate: false,
      followRedirects: false,
    })
    const client = new AppServer(socket, timeoutMs)
    try {
      await new Promise<void>((resolve, reject) => {
        const cleanup = () => { socket.off('open', open); socket.off('error', error); socket.off('close', error); options.signal?.removeEventListener('abort', abort) }
        const open = () => { cleanup(); resolve() }
        const error = () => { cleanup(); reject(new RpcUnavailable('App Server handshake failed', false)) }
        const abort = () => { cleanup(); reject(new RpcUnavailable('App Server connection aborted', false)); socket.terminate() }
        socket.once('open', open); socket.once('error', error); socket.once('close', error)
        options.signal?.addEventListener('abort', abort, { once: true })
      })
      const identity = await client.request<ServerIdentity>('initialize', {
        clientInfo: { name: 'lazymind_workflow', title: 'LazyMind Workflow', version: '0.2.0' },
        capabilities: { experimentalApi: options.experimental ?? false },
      }, options.signal)
      if (!identity || typeof identity.userAgent !== 'string' || typeof identity.codexHome !== 'string'
        || typeof identity.platformOs !== 'string' || typeof identity.platformFamily !== 'string') throw new Error('Invalid App Server identity')
      if (options.expectedHome && !await sameProfile(identity.codexHome, options.expectedHome)) throw new Error('App Server belongs to another Codex profile')
      client.notify('initialized')
      client.ready = true
      return { client, identity }
    } catch (error) { socket.terminate(); throw error }
  }

  request<T>(method: string, params: unknown, signal?: AbortSignal): Promise<T> {
    if (!this.ready && method !== 'initialize') return Promise.reject(new RpcUnavailable('App Server is not initialized', false))
    if (signal?.aborted || this.socket.readyState !== WebSocket.OPEN) return Promise.reject(new RpcUnavailable('RPC not sent: connection unavailable or request aborted', false))
    const id = `${this.prefix}:${++this.seq}`
    return new Promise<T>((resolve, reject) => {
      const abort = () => this.finish(id, new RpcUnavailable('RPC aborted after sending; outcome is uncertain', true))
      const timer = setTimeout(() => this.finish(id, new RpcUnavailable('RPC timed out after sending; outcome is uncertain', true)), this.timeoutMs)
      const cleanup = () => { clearTimeout(timer); signal?.removeEventListener('abort', abort) }
      this.pending.set(id, { resolve: value => resolve(value as T), reject, cleanup })
      signal?.addEventListener('abort', abort, { once: true })
      try {
        this.socket.send(JSON.stringify({ id, method, params }), error => {
          if (error) this.finish(id, new RpcUnavailable('RPC write failed; outcome is uncertain', true))
        })
      } catch { this.finish(id, new RpcUnavailable('RPC write failed; outcome is uncertain', true)) }
    })
  }

  notify(method: string, params?: unknown) {
    if (this.socket.readyState !== WebSocket.OPEN) throw new RpcUnavailable('RPC notification not sent', false)
    this.socket.send(JSON.stringify({ method, ...(params === undefined ? {} : { params }) }))
  }

  /** Caller must explicitly handle native approval/input requests; never approve automatically. */
  respond(id: string | number, result: unknown) {
    if (!this.ready || this.socket.readyState !== WebSocket.OPEN) throw new RpcUnavailable('RPC response not sent', false)
    this.socket.send(JSON.stringify({ id, result }))
  }

  async readThread(threadId: string, signal?: AbortSignal): Promise<NativeThread> {
    const value = await this.request<{ thread: NativeThread }>('thread/read', { threadId, includeTurns: true }, signal)
    if (value?.thread?.id !== threadId || typeof value.thread.status?.type !== 'string') throw new Error('App Server returned another or invalid thread')
    return value.thread
  }
  async startTurn(threadId: string, text: string, clientUserMessageId: string, signal?: AbortSignal) {
    return this.request<{ turn: NativeTurn }>('turn/start', { threadId, input: [{ type: 'text', text }], clientUserMessageId }, signal)
  }
  async steerTurn(threadId: string, expectedTurnId: string, text: string, clientUserMessageId: string, signal?: AbortSignal) {
    return this.request<{ turnId: string }>('turn/steer', { threadId, expectedTurnId, input: [{ type: 'text', text }], clientUserMessageId }, signal)
  }
  async interruptTurn(threadId: string, turnId: string, signal?: AbortSignal) {
    return this.request<Record<string, never>>('turn/interrupt', { threadId, turnId }, signal)
  }
  close() { this.ready = false; this.fail('App Server client closed'); this.socket.terminate() }
  private finish(id: string, error?: Error, value?: unknown) {
    const pending = this.pending.get(id)
    if (!pending) return
    this.pending.delete(id); pending.cleanup()
    if (error) pending.reject(error); else pending.resolve(value)
  }
  private fail(message: string) {
    this.ready = false
    for (const id of this.pending.keys()) this.finish(id, new RpcUnavailable(message, true))
  }
}
